import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, texture, uv, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  root.name = config.id ?? 'collection-card-3';

  const resources = [];
  const primitiveResults = [];
  const textObjects = [];

  const cardWidth = 2.65;
  const cardHeight = 1.72;

  const backdropGeometry = new PlaneGeometry(cardWidth + 0.08, cardHeight + 0.08);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropV = smoothstep(0.0, 1.0, uv().y);
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    backdropV
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-surface';
  backdrop.position.z = -0.025;
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const imageGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true
  });
  const image = new Mesh(imageGeometry, imageMaterial);
  image.name = 'collection-card-image';
  image.position.z = 0.01;
  root.add(image);
  resources.push(imageGeometry, imageMaterial);

  const accentGeometry = new PlaneGeometry(0.055, cardHeight * 0.72);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.name = 'signal-red-edge';
  accent.position.set(-cardWidth * 0.5 + 0.075, 0, 0.035);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (typeof item?.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });

    textObject.name = item.role ?? 'headline';
    textObject.position.set(
      -cardWidth * 0.5 + 0.22,
      -cardHeight * 0.5 + 0.22,
      0.055
    );
    root.add(textObject);
    textObjects.push(textObject);
  }

  if (config.imageUrl) {
    void ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTexture) => {
      loadedTexture.colorSpace = ctx.THREE.SRGBColorSpace;
      imageMaterial.colorNode = texture(loadedTexture);
      imageMaterial.needsUpdate = true;
      resources.push(loadedTexture);
    }).catch(() => {
      imageMaterial.colorNode = mix(
        vec3(0.043, 0.043, 0.063),
        vec3(0.086, 0.086, 0.114),
        backdropV
      );
      imageMaterial.needsUpdate = true;
    });
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive === 'function') {
      const result = applyPrimitive(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const child of textObjects) {
      child.parent?.remove(child);
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}
